#### Scope resolution

```rust
fn resolve_scope(db: &Db, scope: &str) -> Result<Vec<(String, String, String)>>
// Returns Vec<(component_id, component_name, lifecycle_state)>
// Resolution order:
//   1. Exact component name match (case-insensitive)
//   2. Exact component ID match
//   3. Alias lookup via db.find_alias(scope) → component
//   4. File path → component via active_components_with_paths reverse lookup
//   5. Path prefix match (scope as directory → all components with files under it)
// Returns empty vec if nothing matches (caller reports "no component found").
```

#### Drift check from snapshots

```rust
fn check_drift_from_snapshots(
    db: &Db,
    component_id: &str,
    component_name: &str,
) -> Option<serde_json::Value>
// Reads last DRIFT_WINDOW snapshots via db.recent_convention_snapshots
// Checks: enough snapshots, monotonic non-decreasing, delta > DRIFT_THRESHOLD
// If triggered: parse oldest+newest attribute_distribution JSON,
//   call find_diverging_attributes, return alert JSON
// Returns None if no drift detected or insufficient data
```

#### Main handle function

```rust
pub fn handle(db: &Db, scope: &str) -> Result<serde_json::Value> {
    let components = resolve_scope(db, scope)?;
    if components.is_empty() {
        return Ok(json!({
            "scope": scope,
            "error": "no component found matching scope",
            "hint": "use sutra_components to list available components"
        }));
    }

    let all_conventions = db.all_conventions_merged()?;
    let all_proposals = db.pending_proposals()?;

    let mut orientation_sections = Vec::new();

    for (comp_id, comp_name, comp_lifecycle) in &components {
        let is_sketch = comp_lifecycle == "sketch";

        // Filter conventions: component-scoped + global
        let in_scope: Vec<_> = all_conventions.iter()
            .filter(|c| c.component_id.as_deref() == Some(comp_id) 
                        || c.component_id.is_none())
            .collect();

        let conv_ids: Vec<&str> = in_scope.iter().map(|c| c.id.as_str()).collect();
        let templates = db.templates_for_conventions(&conv_ids)?;
        let template_map: HashMap<&str, &str> = templates.iter()
            .map(|t| (t.convention_id.as_str(), t.template_text.as_str()))
            .collect();

        let waivers = db.list_waivers(None)?;
        let in_scope_waivers: Vec<_> = waivers.iter()
            .filter(|w| conv_ids.contains(&w.convention_id.as_str())
                        && (w.component_id == *comp_id || w.component_id.is_empty()))
            .collect();

        let in_scope_proposals: Vec<_> = all_proposals.iter()
            .filter(|p| conv_ids.contains(&p.convention_id.as_str()))
            .collect();

        // Group conventions by effective lifecycle
        // In sketch mode, all conventions flatten to informational
        let mut preferred = Vec::new();
        let mut deprecated = Vec::new();
        let mut forbidden = Vec::new();
        let mut descriptive = Vec::new();

        for c in &in_scope {
            let state = if is_sketch {
                "descriptive" // sketch mode flattens everything
            } else {
                c.lifecycle_state.as_deref().unwrap_or("descriptive")
            };
            let template = template_map.get(c.id.as_str());
            let entry = json!({
                "convention_id": c.id,
                "antecedent": c.antecedent,
                "consequent": c.consequent,
                "support": c.support,
                "confidence": c.confidence,
                "scope": if c.component_id.is_some() { "component" } else { "global" },
                "template": template,
            });
            match state {
                "preferred" => preferred.push(entry),
                "deprecated" => deprecated.push(entry),
                "forbidden" => forbidden.push(entry),
                _ => descriptive.push(entry),
            }
        }

        // Drift check
        let drift = check_drift_from_snapshots(db, comp_id, comp_name);

        // Build section
        let mut section = json!({
            "component_id": comp_id,
            "component_name": comp_name,
            "lifecycle_state": comp_lifecycle,
        });

        if is_sketch {
            section["sketch_mode_note"] = json!(
                "Component is in sketch mode — all conventions are informational only"
            );
        }

        if !preferred.is_empty() {
            section["preferred"] = json!({
                "guidance": "Follow these conventions. Templates show the expected signature shape.",
                "conventions": preferred,
            });
        }
        if !deprecated.is_empty() {
            section["warnings"] = json!({
                "guidance": "Avoid these patterns — they are being phased out.",
                "conventions": deprecated,
            });
        }
        if !forbidden.is_empty() {
            section["anti_patterns"] = json!({
                "guidance": "Do not use these patterns.",
                "conventions": forbidden,
            });
        }
        if !descriptive.is_empty() {
            section["observed_patterns"] = json!({
                "guidance": "Observed patterns in this scope (informational only).",
                "conventions": descriptive,
            });
        }
        if let Some(drift_alert) = drift {
            section["drift_alert"] = drift_alert;
        }
        if !in_scope_waivers.is_empty() {
            section["active_waivers"] = json!(in_scope_waivers.iter().map(|w| {
                json!({
                    "waiver_id": w.id,
                    "convention_id": w.convention_id,
                    "symbol": w.symbol_qualified_name,
                    "rationale": w.rationale,
                    "waived_by": w.waived_by,
                    "created_at": w.created_at,
                })
            }).collect::<Vec<_>>());
        }
        if !in_scope_proposals.is_empty() {
            section["pending_proposals"] = json!(in_scope_proposals.iter().map(|p| {
                json!({
                    "proposal_id": p.id,
                    "convention_id": p.convention_id,
                    "proposed_transition": p.proposed_transition,
                    "signal_rationale": p.signal_rationale,
                    "created_at": p.created_at,
                })
            }).collect::<Vec<_>>());
        }

        orientation_sections.push(section);
    }

    Ok(json!({
        "scope": scope,
        "orientation": orientation_sections,
    }))
}
```

